actions.script:
const asList = (value) => (value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value)))
        .map((id) => String(id).trim()).filter((id) => id)
recipientList = []
const toIds = []
const ccIds = []
for (const id of (toPartyId ? [toPartyId] : []).concat(asList(toPartyIdList))) if (!toIds.includes(id)) toIds.push(id)
for (const id of asList(ccPartyIdList).concat(asList(mentionPartyIdList))) {
    if (!toIds.includes(id) && !ccIds.includes(id)) ccIds.push(id)
}
const named = toIds.concat(ccIds)
if (named.length) {
    const found = new Set(Array.from(ec.entity.find('mantle.party.Party').condition('partyId', 'in', named)
            .selectField('partyId').disableAuthz().list()).map((party) => party.partyId))
    const missing = named.filter((id) => !found.has(id))
    if (missing.length) { ec.message.addError(`Party ${missing.join(', ')} not found`); return }
}
toPartyId = toIds.length ? toIds[0] : null

const findEvent = (id) => ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', id).one()
if (parentCommEventId) {
    const parent = findEvent(parentCommEventId)
    if (parent == null) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
    if (!rootCommEventId) rootCommEventId = parent.rootCommEventId || parent.communicationEventId
}

// the recipients by priority: to, cc, then the mailbox's members and the thread's participants
const roles = new Map()
for (const id of toIds) roles.set(id, 'MessageTo')
for (const id of ccIds) if (!roles.has(id)) roles.set(id, 'MessageCc')
if (contactListId) {
    const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
            .parameters({contactListId: contactListId, partyId: fromPartyId}).call()
    if (!access.exists || !access.canSeeHeader) { ec.message.addError(`Contact list ${contactListId} not found`); return }
    if (access.isMailbox) {
        const listName = access.contactList?.contactListName || contactListId
        if (!access.canPost) {
            ec.message.addError(access.isArchived ? `Mailbox ${listName} is archived` : `You may not post to mailbox ${listName}`)
            return
        }
        let threadEvents = []
        if (rootCommEventId) {
            const root = findEvent(rootCommEventId)
            if (root == null) { ec.message.addError(`Communication event ${rootCommEventId} not found`); return }
            if (root.contactListId !== contactListId) {
                ec.message.addError(`Communication event ${rootCommEventId} is not a post in mailbox ${listName}`); return }
            if (root.statusId === 'CeResolved') { ec.message.addError(`This thread in mailbox ${listName} is closed`); return }
            const cf = ec.entity.conditionFactory
            threadEvents = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent')
                    .condition(cf.makeCondition([cf.makeCondition('communicationEventId', 'equals', rootCommEventId),
                        cf.makeCondition('rootCommEventId', 'equals', rootCommEventId)], 'or'))
                    .condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true))
                    .selectField('communicationEventId').selectField('fromPartyId').selectField('toPartyId').list())
            const threadIds = threadEvents.map((event) => event.communicationEventId)
            const threadRows = threadIds.length ? Array.from(ec.entity.find('mantle.party.communication.CommunicationEventParty')
                    .condition('communicationEventId', 'in', threadIds).list()) : []
            // a poster who may not read every thread (a help mailbox's non-member) posts only in their own
            if (!access.canReadAll && !threadEvents.some((event) => event.fromPartyId === fromPartyId || event.toPartyId === fromPartyId)
                    && !threadRows.some((row) => row.partyId === fromPartyId)) {
                ec.message.addError(`Communication event ${rootCommEventId} not found`); return }
            if (access.isPublic || access.postingEnumId === 'ClpAnyUser') {
                const participants = []
                for (const event of threadEvents) for (const id of [event.fromPartyId, event.toPartyId]) if (id) participants.push(id)
                for (const row of threadRows) if (row.roleTypeId === 'MessageTo' || row.roleTypeId === 'MessageCc') participants.push(row.partyId)
                for (const id of participants) if (id !== fromPartyId && !roles.has(id)) roles.set(id, 'MessageMailbox')
            }
        }
        for (const row of ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
                .condition('statusId', 'CLPT_ACCEPTED').condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null))
                .orderBy('fromDate').list()) {
            if (row.partyId !== fromPartyId && !roles.has(row.partyId)) roles.set(row.partyId, 'MessageMailbox')
        }
    }
}
recipientList = Array.from(roles.entries()).map(([partyId, roleTypeId]) => ({partyId: partyId, roleTypeId: roleTypeId}))

newMailUserIds = []
for (const recipient of recipientList) {
    ec.service.sync().name('create#mantle.party.communication.CommunicationEventParty').parameters({
        communicationEventId: communicationEventId, partyId: recipient.partyId, roleTypeId: recipient.roleTypeId,
        statusId: 'CepReceived'}).call()
    if (ec.message.hasError()) return
}
// the alert of new mail in the Inbox; notify#NewMail logs its own failures
if (communicationEventTypeId === 'Message' && recipientList.length) {
    const alert = ec.service.sync().name('mantle.party.CommunicationServices.notify#NewMail')
            .parameter('communicationEventId', communicationEventId).call()
    newMailUserIds = alert?.notifiedUserIds ?? []
}

const asList = (value) => (value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value)))
        .map((id) => String(id).trim()).filter((id) => id)
const parent = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', parentCommEventId).one()
if (parent == null) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
const isMessage = parent.communicationEventTypeId === 'Message'
communicationEventTypeId = isMessage ? 'Message' : 'Comment'
rootCommEventId = parent.rootCommEventId || parentCommEventId
contactListId = null
const rowsOf = (roleTypeId) => Array.from(ec.entity.find('mantle.party.communication.CommunicationEventParty')
        .condition('communicationEventId', parentCommEventId).condition('roleTypeId', roleTypeId).list()).map((row) => row.partyId)

if (isMessage) {
    // the replier sees the parent: from, to or a recipient of it, or a post of a mailbox it may read
    let visible = parent.fromPartyId === fromPartyId || parent.toPartyId === fromPartyId ||
            ec.entity.find('mantle.party.communication.CommunicationEventParty').condition('communicationEventId', parentCommEventId)
                .condition('partyId', fromPartyId).count() > 0
    if (!visible && parent.contactListId) {
        const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
                .parameters({contactListId: parent.contactListId, partyId: fromPartyId}).call()
        // a help mailbox's non-member only in their own thread, which create#Message checks
        visible = access.isMailbox && (access.canReadAll || access.canReadOwn)
    }
    if (!visible) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
}

const toIds = []
const ccIds = []
const addTo = (id) => { if (id && !toIds.includes(id)) toIds.push(id) }
if (!isMessage || replyToSenderOnly) {
    addTo(parent.fromPartyId === fromPartyId ? parent.toPartyId : parent.fromPartyId)
} else if (parent.contactListId) {
    contactListId = parent.contactListId
} else {
    for (const id of [parent.fromPartyId, parent.toPartyId].concat(rowsOf('MessageTo'))) if (id !== fromPartyId) addTo(id)
    for (const id of rowsOf('MessageCc')) if (id !== fromPartyId && !toIds.includes(id) && !ccIds.includes(id)) ccIds.push(id)
}
for (const id of asList(toPartyIdList)) addTo(id)

const out = ec.service.sync().name('mantle.party.CommunicationServices.create#Message').parameters({
    communicationEventTypeId: communicationEventTypeId, contactMechTypeEnumId: 'CmtWebForm', statusId: statusId,
    parentCommEventId: parentCommEventId, rootCommEventId: rootCommEventId, fromPartyId: fromPartyId,
    toPartyIdList: toIds, ccPartyIdList: ccIds.concat(asList(ccPartyIdList)), mentionPartyIdList: mentionPartyIdList,
    contactListId: contactListId, entryDate: ec.user.nowTimestamp, contentType: contentType, subject: subject, body: body}).call()
if (ec.message.hasError()) return
communicationEventId = out.communicationEventId
toPartyId = out.toPartyId ?? null

const cf = ec.entity.conditionFactory
threadMap = {}
const partyId = ec.user.userAccount?.partyId || null
const rootIds = Array.from(new Set(Array.from(rootCommEventIdList || []).map((id) => String(id))))
if (!partyId || rootIds.length === 0) return
const rootSet = new Set(rootIds)
const events = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent')
        .condition(cf.makeCondition([cf.makeCondition('communicationEventId', 'in', rootIds),
            cf.makeCondition('rootCommEventId', 'in', rootIds)], 'or'))
        .condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true))
        .orderBy('entryDate').orderBy('communicationEventId').list()).map((value) => value.getMap())
if (events.length === 0) return
const eventIds = events.map((event) => event.communicationEventId)

const myRows = new Map()
const recipients = new Map()
for (const value of ec.entity.find('mantle.party.communication.CommunicationEventParty').condition('communicationEventId', 'in', eventIds)
        .condition(cf.makeCondition([cf.makeCondition('partyId', 'equals', partyId),
            cf.makeCondition('roleTypeId', 'in', ['MessageTo', 'MessageCc'])], 'or')).orderBy('partyId').list()) {
    const row = value.getMap()
    if (row.partyId === partyId) {
        if (!myRows.has(row.communicationEventId)) myRows.set(row.communicationEventId, [])
        myRows.get(row.communicationEventId).push({roleTypeId: row.roleTypeId, readDate: row.readDate ?? null,
            isFlagged: row.isFlagged ?? null, archivedDate: row.archivedDate ?? null, snoozedThruDate: row.snoozedThruDate ?? null,
            statusId: row.statusId ?? null})
    }
    if (row.roleTypeId === 'MessageTo' || row.roleTypeId === 'MessageCc') {
        if (!recipients.has(row.communicationEventId)) recipients.set(row.communicationEventId, {to: [], cc: []})
        recipients.get(row.communicationEventId)[row.roleTypeId === 'MessageTo' ? 'to' : 'cc'].push(row.partyId)
    }
}
const attachments = new Map()
for (const value of ec.entity.find('mantle.party.communication.CommunicationEventContent').condition('communicationEventId', 'in', eventIds)
        .orderBy('sequenceNum').orderBy('contentDate').list()) {
    if (!attachments.has(value.communicationEventId)) attachments.set(value.communicationEventId, [])
    attachments.get(value.communicationEventId).push({communicationEventContentId: value.communicationEventContentId,
        contentLocation: value.contentLocation ?? null, description: value.description ?? null,
        contentTypeEnumId: value.contentTypeEnumId ?? null, contentDate: value.contentDate ?? null})
}
const accessByList = new Map()
const accessOf = (contactListId) => {
    if (!accessByList.has(contactListId)) accessByList.set(contactListId, ec.service.sync()
            .name('mantle.marketing.ContactListServices.get#ContactListAccess').parameter('contactListId', contactListId).call())
    return accessByList.get(contactListId)
}

const byThread = new Map()
for (const event of events) {
    const threadId = rootSet.has(event.communicationEventId) ? event.communicationEventId : event.rootCommEventId
    if (!byThread.has(threadId)) byThread.set(threadId, [])
    byThread.get(threadId).push(event)
}
for (const [threadId, messages] of byThread) {
    const mine = (event) => event.fromPartyId === partyId || event.toPartyId === partyId || myRows.has(event.communicationEventId)
    const takesPart = messages.some(mine)
    const visible = messages.filter((event) => {
        if (mine(event)) return true
        if (!event.contactListId) return false
        const access = accessOf(event.contactListId)
        return access.isMailbox && (access.canReadAll || (access.canReadOwn && takesPart))
    })
    if (visible.length === 0) continue
    const root = messages.find((event) => event.communicationEventId === threadId) || null
    const listId = root?.contactListId || null
    const access = listId ? accessOf(listId) : null
    const isMailbox = !!access?.isMailbox
    threadMap[threadId] = {rootCommEventId: threadId, root: root, subject: root?.subject ?? visible[0].subject ?? null,
        contactListId: listId, contactListName: access?.contactList?.contactListName ?? null, isMailbox: isMailbox,
        isClosed: isMailbox && root?.statusId === 'CeResolved', takesPart: takesPart,
        canReadAll: isMailbox ? access.canReadAll : null, canPost: isMailbox ? access.canPost : null,
        canModerate: isMailbox ? access.canModerate : false,
        messageList: visible.map((event) => Object.assign({}, event, {myRowList: myRows.get(event.communicationEventId) || [],
            toPartyIdList: recipients.get(event.communicationEventId)?.to ?? [],
            ccPartyIdList: recipients.get(event.communicationEventId)?.cc ?? [],
            attachmentList: attachments.get(event.communicationEventId) || []}))}
}

const cf = ec.entity.conditionFactory
const DELIVERY = ['MessageTo', 'MessageCc', 'MessageMailbox']
const TYPES = ['Message', 'Comment']
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
threadList = []
hasMore = false
nextBeforeDate = null
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) { ec.message.addError('Internal messages need a user with a party'); return }
if (!view) view = contactListId ? 'all' : 'received'
if (!['received', 'sent', 'flagged', 'snoozed', 'archived', 'all'].includes(view)) {
    ec.message.addError(`Unknown view ${view}: received, sent, flagged, snoozed, archived or all`); return }
if (!(pageSize > 0)) pageSize = 50
const now = ec.user.nowTimestamp
const nowMillis = toMillis(now)

if (contactListId) {
    const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
            .parameter('contactListId', contactListId).call()
    if (!access.exists || !access.isMailbox || !access.canSeeHeader) { ec.message.addError(`Mailbox ${contactListId} not found`); return }
    // a join request sees only the header
    if (!access.canReadOwn) return
}
// the Inbox leaves out the posts of the mailboxes the user takes as Mailbox only
let mailboxOnlyIds = []
if (view === 'received' && !contactListId) {
    const memberRows = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('partyId', partyId)
            .condition('statusId', 'CLPT_ACCEPTED').condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
    const listIds = Array.from(new Set(memberRows.map((row) => row.contactListId)))
    const defaults = {}
    if (listIds.length) for (const list of ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', 'in', listIds)
            .selectField('contactListId').selectField('defaultDeliveryEnumId').list()) defaults[list.contactListId] = list.defaultDeliveryEnumId
    mailboxOnlyIds = Array.from(new Set(memberRows.filter((row) => (row.deliveryEnumId || defaults[row.contactListId] || 'CldInbox') === 'CldMailboxOnly')
            .map((row) => row.contactListId)))
}

const notCancelled = cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true)
const textCondition = searchText ? cf.makeCondition([cf.makeCondition('subject', 'like', `%${searchText}%`, false, true),
    cf.makeCondition('body', 'like', `%${searchText}%`, false, true)], 'or') : null
// the messages that put a thread in the view
const byEvents = view === 'sent' || (contactListId && view === 'all')
const makeFind = () => {
    let find
    if (byEvents) {
        find = ec.entity.find('mantle.party.communication.CommunicationEvent')
        if (view === 'sent') find = find.condition('fromPartyId', partyId).condition(cf.makeCondition([
            cf.makeCondition('communicationEventTypeId', 'equals', 'Message'), cf.makeCondition('toPartyId', 'not-equals', null),
            cf.makeCondition('contactListId', 'not-equals', null)], 'or'))
    } else {
        find = ec.entity.find('mantle.party.communication.CommunicationEventPartyAndEvent').condition('partyId', partyId)
                .condition('roleTypeId', 'in', DELIVERY)
        const notSnoozed = cf.makeCondition([cf.makeCondition('snoozedThruDate', 'equals', null),
            cf.makeCondition('snoozedThruDate', 'less-equals', now)], 'or')
        if (view === 'received') {
            find = find.condition('archivedDate', null).condition(notSnoozed)
            if (mailboxOnlyIds.length) find = find.condition(cf.makeCondition([cf.makeCondition('roleTypeId', 'in', ['MessageTo', 'MessageCc']),
                cf.makeCondition('contactListId', 'not-in', mailboxOnlyIds)], 'or'))
        } else if (view === 'flagged') find = find.condition('isFlagged', 'Y')
        else if (view === 'snoozed') find = find.condition('archivedDate', null).condition(cf.makeCondition('snoozedThruDate', 'greater', now))
        else if (view === 'archived') find = find.condition(cf.makeCondition('archivedDate', 'not-equals', null))
        if (unreadOnly) find = find.condition('readDate', null)
    }
    find = find.condition('communicationEventTypeId', 'in', TYPES).condition(notCancelled)
    if (contactListId) find = find.condition('contactListId', contactListId)
    if (textCondition) find = find.condition(textCondition)
    return find.selectField('communicationEventId').selectField('rootCommEventId').selectField('entryDate')
}

const textOf = (body) => body ? String(body).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim() : ''
const summarize = (thread, sortDate) => {
    const messages = thread.messageList
    const deliveryRows = messages.flatMap((message) => message.myRowList.filter((row) => DELIVERY.includes(row.roleTypeId)))
    const unreadCount = messages.filter((message) => message.myRowList.some((row) => DELIVERY.includes(row.roleTypeId) && row.readDate == null)).length
    const isArchived = deliveryRows.length > 0 && deliveryRows.every((row) => row.archivedDate != null)
    if (view === 'archived' && !isArchived) return null
    if (unreadOnly && unreadCount === 0) return null
    const snoozes = deliveryRows.filter((row) => row.archivedDate == null).map((row) => toMillis(row.snoozedThruDate))
            .filter((millis) => millis != null && millis > nowMillis)
    const participants = []
    for (const message of messages) for (const id of [message.fromPartyId].concat(message.toPartyIdList, message.ccPartyIdList, [message.toPartyId])) {
        if (id && !participants.includes(id)) participants.push(id)
    }
    const first = messages[0]
    const last = messages[messages.length - 1]
    const snippet = textOf(last.body)
    return {store: 'internal', threadId: thread.rootCommEventId, rootCommEventId: thread.rootCommEventId,
        lastCommEventId: last.communicationEventId, communicationEventTypeId: (thread.root || first).communicationEventTypeId,
        subject: thread.subject, snippet: snippet.length > 140 ? snippet.substring(0, 137) + '...' : snippet,
        sortDate: sortDate, lastDate: toMillis(last.entryDate), firstDate: toMillis(first.entryDate),
        messageCount: messages.length, replyCount: messages.length - 1, unreadCount: unreadCount, isUnread: unreadCount > 0,
        isFlagged: messages.some((message) => message.myRowList.some((row) => row.isFlagged === 'Y')), isArchived: isArchived,
        snoozedThruDate: snoozes.length ? Math.max.apply(null, snoozes) : null,
        hasAttachment: messages.some((message) => message.attachmentList.length > 0), fromPartyId: last.fromPartyId ?? null,
        participantPartyIdList: participants, participantList: [], contactListId: thread.isMailbox ? thread.contactListId : null,
        contactListName: thread.isMailbox ? thread.contactListName : null, isClosed: thread.isClosed}
}

// scan the view's messages newest first; a thread comes at its newest one
const beforeMillis = toMillis(beforeDate)
const chunkSize = Math.max(pageSize * 2, 50)
const seen = new Set()
const accepted = []
let offset = 0
while (accepted.length <= pageSize) {
    let find = makeFind()
    if (beforeMillis != null) find = find.condition(cf.makeCondition('entryDate', 'less', new Date(beforeMillis)))
    const rows = Array.from(find.orderBy('-entryDate').orderBy('-communicationEventId').offset(offset).limit(chunkSize).list())
    offset += rows.length
    const fresh = []
    for (const row of rows) {
        const threadId = row.rootCommEventId || row.communicationEventId
        if (seen.has(threadId)) continue
        seen.add(threadId)
        fresh.push({threadId: threadId, sortDate: toMillis(row.entryDate)})
    }
    if (fresh.length) {
        // a thread with a message in the view at or after the cursor was on an earlier page
        let shown = new Set()
        if (beforeMillis != null) {
            const ids = fresh.map((candidate) => candidate.threadId)
            shown = new Set(Array.from(makeFind().condition(cf.makeCondition([cf.makeCondition('communicationEventId', 'in', ids),
                cf.makeCondition('rootCommEventId', 'in', ids)], 'or')).condition(cf.makeCondition('entryDate', 'greater-equals',
                new Date(beforeMillis))).list()).map((row) => row.rootCommEventId || row.communicationEventId))
        }
        const candidates = fresh.filter((candidate) => !shown.has(candidate.threadId))
        const threadMap = candidates.length ? ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThreadMessages')
                .parameter('rootCommEventIdList', candidates.map((candidate) => candidate.threadId)).call().threadMap : {}
        if (ec.message.hasError()) return
        for (const candidate of candidates) {
            const thread = threadMap[candidate.threadId]
            const summary = thread ? summarize(thread, candidate.sortDate) : null
            if (summary == null) continue
            accepted.push(summary)
            if (accepted.length > pageSize) break
        }
    }
    if (rows.length < chunkSize) break
}
hasMore = accepted.length > pageSize
threadList = accepted.slice(0, pageSize)
if (hasMore) nextBeforeDate = threadList[threadList.length - 1].sortDate

// the participants' names
const partyIds = Array.from(new Set(threadList.flatMap((thread) => thread.participantPartyIdList)))
if (partyIds.length) {
    const names = {}
    for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', partyIds).disableAuthz().list())
        names[party.partyId] = party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.partyId
    for (const thread of threadList) thread.participantList = thread.participantPartyIdList.map((id) => ({partyId: id, name: names[id] || id}))
}

const DELIVERY = ['MessageTo', 'MessageCc', 'MessageMailbox']
messageList = []
participantList = []
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) { ec.message.addError('Internal messages need a user with a party'); return }
const wanted = communicationEventId || rootCommEventId
if (!wanted) { ec.message.addError('A communicationEventId or rootCommEventId is required'); return }
if (!rootCommEventId) {
    const event = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
    if (event == null) { ec.message.addError(`Communication event ${communicationEventId} not found`); return }
    rootCommEventId = event.rootCommEventId || event.communicationEventId
}
const thread = ec.service.sync().name('mantle.party.CommunicationServices.get#InternalThreadMessages')
        .parameter('rootCommEventIdList', [rootCommEventId]).call().threadMap[rootCommEventId]
if (ec.message.hasError()) return
if (thread == null || (communicationEventId && !thread.messageList.some((message) => message.communicationEventId === communicationEventId))) {
    ec.message.addError(`Communication event ${wanted} not found`); return }
subject = thread.subject
contactListId = thread.isMailbox ? thread.contactListId : null
contactListName = thread.isMailbox ? thread.contactListName : null
isClosed = thread.isClosed
canModerate = thread.canModerate
canReply = !isClosed && (!thread.isMailbox || thread.canPost === true)
unreadCount = 0
const participants = []
for (const message of thread.messageList) {
    const rows = message.myRowList
    const row = rows.find((candidate) => DELIVERY.includes(candidate.roleTypeId)) || rows[0] || null
    const isUnread = rows.some((candidate) => DELIVERY.includes(candidate.roleTypeId) && candidate.readDate == null)
    if (isUnread) unreadCount++
    messageList.push({communicationEventId: message.communicationEventId, parentCommEventId: message.parentCommEventId ?? null,
        rootCommEventId: message.rootCommEventId ?? null, communicationEventTypeId: message.communicationEventTypeId ?? null,
        statusId: message.statusId ?? null, fromPartyId: message.fromPartyId ?? null, toPartyId: message.toPartyId ?? null,
        toPartyIdList: message.toPartyIdList, ccPartyIdList: message.ccPartyIdList, entryDate: message.entryDate ?? null,
        subject: message.subject ?? null, body: message.body ?? null, contentType: message.contentType ?? null,
        contactListId: message.contactListId ?? null, attachmentList: message.attachmentList,
        myState: row == null ? null : {roleTypeId: row.roleTypeId, readDate: row.readDate, isFlagged: row.isFlagged,
            archivedDate: row.archivedDate, snoozedThruDate: row.snoozedThruDate},
        isUnread: isUnread})
    for (const id of [message.fromPartyId].concat(message.toPartyIdList, message.ccPartyIdList, [message.toPartyId])) {
        if (id && !participants.includes(id)) participants.push(id)
