        statusId: 'CepReceived', readDate: ec.user.nowTimestamp}).call()
    if (ec.message.hasError()) return
    rows = findRows()
}
const now = ec.user.nowTimestamp
const changed = new Set()
for (const row of rows) {
    if (read === true && row.readDate == null) row.set('readDate', now)
    if (read === false) row.set('readDate', null)
    if (flagged != null) row.set('isFlagged', flagged ? 'Y' : 'N')
    if (archived === true && row.archivedDate == null) row.set('archivedDate', now)
    if (archived === false) row.set('archivedDate', null)
