// the internal view of each view that has one
const INTERNAL_VIEWS = {inbox: 'received', received: 'received', sent: 'sent', flagged: 'flagged', snoozed: 'snoozed',
    archive: 'archived', archived: 'archived', all: 'all'}
const EMAIL_ALIASES = {received: 'inbox', archived: 'archive'}
if (store && !STORES.includes(store)) { ec.message.addError(`Unknown store ${store}: email or internal`); return }

// each store's own date, or 'end'
const cursorOf = {}
if (cursor) {
    for (const part of String(cursor).split(',')) {
        const [name, value] = part.split(':')
        if (!STORES.includes(name) || !(value === 'end' || /^\d+$/.test(value || ''))) {
            ec.message.addError(`Not an Inbox cursor: ${cursor}`); return }
        cursorOf[name] = value === 'end' ? 'end' : Number(value)
    }
}

// the stores of the view and their parameters
let emailParameters = null
let internalParameters = null
const emailOnlyFilter = !!(fromAddress || toAddress || subject || hasAttachment != null || fromDate != null || thruDate != null ||
        minSize != null || maxSize != null)
const shared = {searchText: searchText, unreadOnly: unreadOnly}
if (contactListId) {
    if (emailAccountId || emailFolderId || emailLabelId || store === 'email') {
        ec.message.addError('A mailbox is listed without an email account, folder or label'); return }
    const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
            .parameter('contactListId', contactListId).call()
    if (ec.message.hasError()) return
