        }
        if (emailFolderId && !reaches('moqui.basic.email.EmailFolder', 'emailFolderId', emailFolderId, 'Email folder')) return
        if (emailLabelId && !reaches('moqui.basic.email.EmailLabel', 'emailLabelId', emailLabelId, 'Email label')) return
        emailParameters = Object.assign({view: emailView, emailAccountId: emailAccountId, emailFolderId: emailFolderId,
            emailLabelId: emailLabelId, threadMode: threadMode, fromAddress: fromAddress, toAddress: toAddress, subject: subject,
            hasAttachment: hasAttachment, fromDate: fromDate, thruDate: thruDate, minSize: minSize, maxSize: maxSize}, shared)
        const internalView = INTERNAL_VIEWS[emailView]
        if (!account && !emailFolderId && !emailLabelId && store !== 'email' && internalView && !emailOnlyFilter)
            internalParameters = Object.assign({view: internalView}, shared)
    }
}
const stores = []
if (emailParameters) stores.push({name: 'email', service: 'org.moqui.impl.EmailClientServices.find#Messages', parameters: emailParameters})
