        return false
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
// each part in a transaction of its own, so one that fails does not roll back the others
const callService = (name, parameters) => {
    const out = ec.service.sync().name(name).parameters(parameters || {}).requireNewTransaction(true).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    if (out == null) throw new Error(`${name} answered nothing`)
    return out
}
const emailOk = part('email', () => {
    const out = callService('org.moqui.impl.EmailClientServices.get#UserEmailAccounts')
    accountList = Array.from(out.accountList || []).map((account) => Object.assign({}, account))
    internalEmailAccountId = out.internalEmailAccountId ?? null
    emailUnreadCount = accountList.filter((account) => !account.isInternal).reduce((sum, account) => sum + (account.unreadCount || 0), 0)
})
const internalOk = part('internal', () => {
