        lastPostDate: list.lastPostDate ?? null}))
})
if (emailOk && internalOk) unifiedUnreadCount = emailUnreadCount + internalUnreadCount

const cf = ec.entity.conditionFactory
notifiedUserIds = []
coalescedUserIds = []
newCount = 0
const textOf = (body) => body ? String(body).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim() : ''
const summaryOf = (subjectText, body) => {
    const text = textOf(body)
    return subjectText || (text.length > 120 ? text.substring(0, 117) + '...' : text)
}
ec.message.pushErrors()
try {
    let userIds = []
    let message = null
    let record = null
    let actorUserId = null
    let earlier = false
    if (emailMessageId) {
        const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).disableAuthz().one()
        if (email == null || !email.emailAccountId || email.statusId !== 'ES_RECEIVED' || email.isRead === 'Y' || email.archivedDate != null) return
        if (email.snoozedThruDate != null && Number(email.snoozedThruDate) > Number(ec.user.nowTimestamp)) return
        const folder = email.emailFolderId ? ec.entity.find('moqui.basic.email.EmailFolder').condition('emailFolderId', email.emailFolderId)
                .disableAuthz().one() : null
        if (folder == null || folder.folderKindEnumId !== 'EfkInbox') return
        const account = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', email.emailAccountId).disableAuthz().one()
        if (account == null || account.statusId === 'EasRemoved') return
        const users = new Set(account.ownerUserId ? [account.ownerUserId] : [])
        for (const row of ec.entity.find('moqui.basic.email.EmailAccountUser').condition('emailAccountId', email.emailAccountId)
                .conditionDate('fromDate', 'thruDate', null).disableAuthz().list()) users.add(row.userId)
        userIds = Array.from(users)
        // the burst this message is in: the account's unread received mail in an Inbox stored within the window
        newCount = 1
        const windowMillis = (coalesceSeconds == null ? 15 : Number(coalesceSeconds)) * 1000
        const stampOf = (row) => {
            const value = row.lastUpdatedStamp
