                .selectField('userId').disableAuthz().list()).map((account) => account.userId) : [])
        userIds = Array.from(new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition('partyId', 'in', partyIds)
                .selectField('userId').disableAuthz().list()).map((account) => account.userId))).filter((userId) => !senders.has(userId))
        let fromName = ''
        if (event.fromPartyId) {
            const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', event.fromPartyId).disableAuthz().one()
            fromName = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || event.fromPartyId) : event.fromPartyId
        }
        message = {store: 'internal', communicationEventId: communicationEventId, threadId: event.rootCommEventId || communicationEventId,
            emailAccountId: null, contactListId: event.contactListId ?? null, contactListName: contactListName, fromName: fromName,
            fromAddress: null, subject: event.subject ?? '', summary: summaryOf(event.subject, event.body)}
        record = ['mantle.party.communication.CommunicationEvent', communicationEventId]
        actorUserId = senders.size ? Array.from(senders)[0] : null
        newCount = 1
        message.newCount = 1
    } else {
        return
    }
    if (userIds.length === 0) return
    // a message after the first of its burst: the burst's alert is the first one's
    if (earlier) { coalescedUserIds = userIds; newCount = 0; return }
    const nm = ec.makeNotificationMessage().topic('NewMail').message(message).userIds(userIds).record(record[0], record[1])
    if (actorUserId) nm.actorUserId(actorUserId)
    nm.send()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? [])
} catch (err) {
    ec.logger.error(`New mail alert for ${emailMessageId ? 'email message ' + emailMessageId : 'communication event ' + communicationEventId} not sent: ${err && err.message ? err.message : err}`)
    notifiedUserIds = []
} finally {
    if (ec.message.hasError()) ec.logger.error(`New mail alert for ${emailMessageId || communicationEventId}: ${ec.message.getErrorsString()}`)
    ec.message.clearErrors()
    ec.message.popErrors()
}

service-call.in-map:
{communicationEventTypeId:'Comment', contactMechTypeEnumId:'CmtWebForm', statusId:'CeSent',
                        fromPartyId:ec.user.userAccount.partyId, entryDate:ec.user.nowTimestamp,
                        contentType:contentType, subject:subject, body:body}

actions.script:
const commEventJoins = {
    'mantle.order.OrderHeader': {entityName: 'mantle.order.OrderCommunicationEvent', keyField: 'orderId'},
    'mantle.request.Request': {entityName: 'mantle.request.RequestCommEvent', keyField: 'requestId'},
    'mantle.work.effort.WorkEffort': {entityName: 'mantle.work.effort.WorkEffortCommEvent', keyField: 'workEffortId'},
    'moqui.resource.wiki.WikiPage': {entityName: 'mantle.party.communication.WikiPageCommunicationEvent', keyField: 'wikiPageId'}}
const workEffortJoins = {
    'mantle.request.Request': {entityName: 'mantle.request.RequestWorkEffort', keyField: 'requestId'},
    'moqui.resource.wiki.WikiPage': {entityName: 'mantle.work.effort.WikiPageWorkEffort', keyField: 'wikiPageId'}}
const noteEntities = {
    'mantle.party.Party': {entityName: 'mantle.party.PartyNote', keyField: 'partyId'},
    'mantle.work.effort.WorkEffort': {entityName: 'mantle.work.effort.WorkEffortNote', keyField: 'workEffortId'},
    'mantle.request.Request': {entityName: 'mantle.request.RequestNote', keyField: 'requestId'},
    'mantle.order.OrderHeader': {entityName: 'mantle.order.OrderNote', keyField: 'orderId'},
    'mantle.facility.Facility': {entityName: 'mantle.facility.FacilityNote', keyField: 'facilityId'}}
// the record types with a *Content entity: the 13 with create and save services, and Facility
const content = (entityName, keyField, typeField, dateField) =>
        ({entityName: entityName, keyField: keyField, typeField: typeField, dateField: dateField || 'contentDate'})
const contentEntities = {
    'mantle.party.agreement.Agreement': content('mantle.party.agreement.AgreementContent', 'agreementId', 'contentTypeEnumId'),
    'mantle.product.maintenance.AssetMaintenance': content('mantle.product.maintenance.AssetMaintenanceContent',
            'assetMaintenanceId', 'contentTypeEnumId'),
    'mantle.party.communication.CommunicationEvent': content('mantle.party.communication.CommunicationEventContent',
            'communicationEventId', 'contentTypeEnumId'),
    'mantle.account.invoice.Invoice': content('mantle.account.invoice.InvoiceContent', 'invoiceId', 'contentTypeEnumId'),
    'mantle.order.OrderHeader': content('mantle.order.OrderContent', 'orderId', 'orderContentTypeEnumId'),
    'mantle.party.Party': content('mantle.party.PartyContent', 'partyId', 'partyContentTypeEnumId'),
    'mantle.account.payment.Payment': content('mantle.account.payment.PaymentContent', 'paymentId', 'contentTypeEnumId'),
    'mantle.account.method.PaymentMethod': content('mantle.account.method.PaymentMethodContent', 'paymentMethodId', 'contentTypeEnumId'),
    'mantle.product.Product': content('mantle.product.ProductContent', 'productId', 'productContentTypeEnumId', 'fromDate'),
    'mantle.product.category.ProductCategory': content('mantle.product.category.ProductCategoryContent',
            'productCategoryId', 'categoryContentTypeEnumId', 'fromDate'),
    'mantle.request.Request': content('mantle.request.RequestContent', 'requestId', 'contentTypeEnumId'),
    'mantle.shipment.Shipment': content('mantle.shipment.ShipmentContent', 'shipmentId', 'shipmentContentTypeEnumId'),
    'mantle.work.effort.WorkEffort': content('mantle.work.effort.WorkEffortContent', 'workEffortId', 'contentTypeEnumId'),
    'mantle.facility.Facility': content('mantle.facility.FacilityContent', 'facilityId', 'facilityContentTypeEnumId')}

const PARTY = 'mantle.party.Party'
const WORK_EFFORT = 'mantle.work.effort.WorkEffort'
const REQUEST = 'mantle.request.Request'
const COMM_EVENT = 'mantle.party.communication.CommunicationEvent'
const ORDER = 'mantle.order.OrderHeader'
const WIKI_PAGE = 'moqui.resource.wiki.WikiPage'
recordVisible = null
notVisibleReason = null
// a refusal: an error, or with checkOnly the answer false
const refuse = (message) => {
    if (checkOnly) { recordVisible = false; notVisibleReason = message }
    else ec.message.addError(message)
}

let recordValue
try { recordValue = ec.entity.makeValue(recordEntityName) }
catch (err) { refuse(`The record type ${recordEntityName} is not an entity`); return }
recordEntityName = recordValue.getEntityName()
recordTypeName = recordValue.getEntityNamePretty()
const keyNames = Object.keys(recordValue.getPrimaryKeys())
if (keyNames.length !== 1) {
    refuse(`The record type ${recordEntityName} has ${keyNames.length} primary key fields, a record link needs one`)
    return
}
recordKeyField = keyNames[0]
isParty = recordEntityName === PARTY
commEventJoin = commEventJoins[recordEntityName] || null
workEffortJoin = workEffortJoins[recordEntityName] || null
noteEntity = noteEntities[recordEntityName] || null
contentEntity = contentEntities[recordEntityName] || null
if (!checkRecord && !checkOnly) return

// ===== whether the user may see the record (see the description) =====
const cf = ec.entity.conditionFactory
const authzOn = !ec.artifactExecution.authzDisabled()
const current = () => cf.makeConditionDate('fromDate', 'thruDate', null)

// the user's party and the organizations of the organization filter (orgIds null: no organization filter)
let scope = null
const userScope = () => {
    if (scope) return scope
    const userPartyId = ec.user.userAccount?.partyId || null
    let orgIds = null
    if (authzOn) {
        if (userPartyId && ec.user.context.filterOrgIds === undefined)
            ec.service.sync().name('mantle.party.PartyServices.setup#UserOrganizationInfo').call()
        const filterSets = () => new Set(Array.from(ec.artifactExecution.getFindFiltersForUser(PARTY) || [])
                .map((filter) => filter.entityFilterSetId))
        const activeOrgId = ec.user.context.activeOrgId || null
        const filterOrgIds = Array.from(ec.user.context.filterOrgIds || [])
        let sets = filterSets()
        if (sets.has('MANTLE_USER_ORG')) orgIds = filterOrgIds
        else if (sets.has('MANTLE_ACTIVE_ORG')) orgIds = activeOrgId ? [activeOrgId] : filterOrgIds
        else if (!activeOrgId) {
            // MANTLE_ACTIVE_ORG applies only with an active organization (its applyCond): whether the
            // authorization names it is asked with one in the user context for the moment
            const hadActive = 'activeOrgId' in ec.user.context
            const oldActive = ec.user.context.activeOrgId
            ec.user.context.activeOrgId = '_NA_'
            try { sets = filterSets() } finally {
                if (hadActive) ec.user.context.activeOrgId = oldActive ?? null
                else delete ec.user.context.activeOrgId
            }
            if (sets.has('MANTLE_ACTIVE_ORG')) orgIds = filterOrgIds
        }
    }
    scope = {userPartyId: userPartyId, orgIds: orgIds, partyIds: (userPartyId ? [userPartyId] : []).concat(orgIds || [])}
    return scope
}
// the mailboxes whose every post the user may read, and the others
let mailboxes = null
const mailboxAccess = () => {
    if (mailboxes) return mailboxes
    const out = ec.service.sync().name('mantle.marketing.ContactListServices.get#UserMailboxAccess')
            .parameter('partyId', userScope().userPartyId).call()
    mailboxes = {readable: Array.from(out?.readableContactListIds || []), hidden: Array.from(out?.hiddenContactListIds || [])}
    return mailboxes
}
// staff: ADMIN, or an explicit entity authorization for the record type (not the inherited one of an app root)
const staff = {}
const staffSees = (entityName) => {
    if (Object.prototype.hasOwnProperty.call(staff, entityName)) return staff[entityName]
    let sees = false
    try {
        if (ec.user.isInGroup('ADMIN')) {
            sees = true
        } else {
            const groupIds = Array.from(ec.user.getUserGroupIdSet() || [])
            const rows = Array.from(ec.entity.find('moqui.security.ArtifactAuthzCheckView').condition('userGroupId', 'in', groupIds)
                    .condition('artifactTypeEnumId', 'AT_ENTITY').condition('authzActionEnumId', 'in', ['AUTHZA_ALL', 'AUTHZA_VIEW'])
                    .disableAuthz().list()).filter((row) => {
                if (row.nameIsPattern !== 'Y') return row.artifactName === entityName
                try { return new RegExp(`^(?:${row.artifactName})$`).test(entityName) }
                catch (err) {
                    ec.logger.error(`Artifact authz ${row.artifactAuthzId}: the pattern ${row.artifactName} is not valid, skipped: ${err}`)
                    return false
                }
            })
            sees = rows.some((row) => row.authzTypeEnumId === 'AUTHZT_ALLOW' || row.authzTypeEnumId === 'AUTHZT_ALWAYS')
                    && !rows.some((row) => row.authzTypeEnumId === 'AUTHZT_DENY')
                    && ec.artifactExecution.isPermitted(entityName, 'AT_ENTITY', 'view')
        }
    } catch (err) {
        ec.logger.error(`Record visibility: the entity authorization of user ${ec.user.userId} for ${entityName} was not read, ` +
                `the per-user rules apply: ${err}`)
        sees = false
    }
    staff[entityName] = sees
    return sees
}

const workEffortVisible = (workEffort, s) => {
    if (s.partyIds.length === 0) return false
    const ids = [workEffort.workEffortId]
    let root = null
    if (workEffort.rootWorkEffortId && workEffort.rootWorkEffortId !== workEffort.workEffortId) {
        ids.push(workEffort.rootWorkEffortId)
        root = ec.entity.find(WORK_EFFORT).condition('workEffortId', workEffort.rootWorkEffortId).disableAuthz().one()
    }
    if ([workEffort.ownerPartyId, root?.ownerPartyId].some((partyId) => partyId && s.partyIds.includes(partyId))) return true
    return ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', 'in', ids)
            .condition('partyId', 'in', s.partyIds).condition(current()).disableAuthz().count() > 0
}
const requestVisible = (request, s) => {
    if (s.userPartyId && request.filedByPartyId === s.userPartyId) return true
    if (s.partyIds.length && ec.entity.find('mantle.request.RequestParty').condition('requestId', request.requestId)
            .condition('partyId', 'in', s.partyIds).condition(current()).disableAuthz().count() > 0) return true
    if (s.orgIds.length === 0) return false
    const store = request.productStoreId ? ec.entity.find('mantle.product.store.ProductStore')
            .condition('productStoreId', request.productStoreId).disableAuthz().one() : null
    if (store?.organizationPartyId && s.orgIds.includes(store.organizationPartyId)) return true
    const facility = request.facilityId ? ec.entity.find('mantle.facility.Facility')
            .condition('facilityId', request.facilityId).disableAuthz().one() : null
    return !!(facility?.ownerPartyId && s.orgIds.includes(facility.ownerPartyId))
}
const orderVisible = (order, s) => {
    if (s.userPartyId && order.enteredByPartyId === s.userPartyId) return true
    if (s.partyIds.length === 0) return false
    // a part of the user's party or organizations as vendor or customer, as the OrderPart filter has it
    if (Array.from(ec.entity.find('mantle.order.OrderPart').condition('orderId', order.orderId).disableAuthz().list())
            .some((part) => s.partyIds.includes(part.vendorPartyId) || s.partyIds.includes(part.customerPartyId))) return true
    return ec.entity.find('mantle.order.OrderPartParty').condition('orderId', order.orderId)
            .condition('partyId', 'in', s.partyIds).disableAuthz().count() > 0
}
// the view rule of org.moqui.impl.WikiServices.get#WikiPageInfo (see the description)
const wikiPageVisible = (page) => {
    const userId = ec.user.userId || null
    const space = page.wikiSpaceId ? ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', page.wikiSpaceId)
            .disableAuthz().one() : null
    if (space == null) return false
    if (space.restrictView === 'Y' && !(userId && ec.entity.find('moqui.resource.wiki.WikiSpaceUser')
            .condition({wikiSpaceId: page.wikiSpaceId, userId: userId, allowView: 'Y'}).disableAuthz().count() > 0)) return false
    if (page.restrictView === 'Y' && !(userId && ec.entity.find('moqui.resource.wiki.WikiPageUser')
            .condition({wikiPageId: page.wikiPageId, userId: userId, allowView: 'Y'}).disableAuthz().count() > 0)) return false
    return true
}
let visible
const commEventVisible = (commEvent, depth) => {
    const s = userScope()
    const mailbox = commEvent.contactListId ? mailboxAccess() : null
    const hiddenPost = !!(mailbox && mailbox.hidden.includes(commEvent.contactListId))
    const eventIds = [commEvent.communicationEventId]
    if (commEvent.rootCommEventId && commEvent.rootCommEventId !== commEvent.communicationEventId) eventIds.push(commEvent.rootCommEventId)
    // a comment on a wiki page the user may not see, the event's or its thread root's, is kept as a mailbox post is
    const onHiddenWikiPage = () => Array.from(ec.entity.find('mantle.party.communication.WikiPageCommunicationEvent')
            .condition('communicationEventId', 'in', eventIds).disableAuthz().list()).some((row) => {
        const page = ec.entity.find(WIKI_PAGE).condition('wikiPageId', row.wikiPageId).disableAuthz().one()
        return page == null || !wikiPageVisible(page)
    })
    if (s.orgIds == null && !hiddenPost && !onHiddenWikiPage()) return true
    if (staffSees(COMM_EVENT)) return true
    const partyId = s.userPartyId
    if (partyId && (commEvent.fromPartyId === partyId || commEvent.toPartyId === partyId)) return true
    if (partyId && ec.entity.find('mantle.party.communication.CommunicationEventParty')
            .condition('communicationEventId', commEvent.communicationEventId).condition('partyId', partyId)
            .disableAuthz().count() > 0) return true
    if (mailbox && mailbox.readable.includes(commEvent.contactListId)) return true
    if (depth > 0) return false
    // filed on a record the user may see: the event, or the root of its thread (a record's timeline shows the replies)
    for (const [linkedEntityName, join] of Object.entries(commEventJoins)) {
        for (const row of ec.entity.find(join.entityName).condition('communicationEventId', 'in', eventIds).disableAuthz().list()) {
            if (visible(linkedEntityName, join.keyField, row[join.keyField], depth + 1)) return true
        }
    }
    for (const row of ec.entity.find('mantle.party.communication.CommunicationEventRecord')
            .condition('communicationEventId', 'in', eventIds).disableAuthz().list()) {
        let keyField = null
        try {
            const keys = Object.keys(ec.entity.makeValue(row.recordEntityName).getPrimaryKeys())
            if (keys.length === 1) keyField = keys[0]
        } catch (err) { keyField = null }
        if (keyField == null) {
            ec.logger.warn(`Communication event ${row.communicationEventId} is filed on ${row.recordEntityName} ${row.recordId}, ` +
                    'which is not a record type, skipped')
            continue
        }
        if (visible(row.recordEntityName, keyField, row.recordId, depth + 1)) return true
    }
    return false
}
visible = (entityName, keyField, id, depth) => {
    // under the user's entity filters
    const value = ec.entity.find(entityName).condition(keyField, id).one()
    if (value == null) return false
    if (entityName === PARTY) return !value.privateOwnerUserId || value.privateOwnerUserId === ec.user.userId
    if (!authzOn) return true
    if (entityName === COMM_EVENT) return commEventVisible(value, depth)
    if (entityName === WIKI_PAGE) return wikiPageVisible(value)
    if (entityName !== WORK_EFFORT && entityName !== REQUEST && entityName !== ORDER) return true
    const s = userScope()
    if (s.orgIds == null || staffSees(entityName)) return true
    if (entityName === ORDER) return orderVisible(value, s)
    return entityName === WORK_EFFORT ? workEffortVisible(value, s) : requestVisible(value, s)
}

// strict: a check that fails (an exception, or an error from a service it calls) is not visible, and logged
let isVisible = false
ec.message.pushErrors()
try {
    isVisible = visible(recordEntityName, recordKeyField, recordId, 0)
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
} catch (err) {
    ec.logger.error(`Record visibility of ${recordEntityName} ${recordId} for user ${ec.user.userId} not checked, not visible: ` +
            `${err && err.message ? err.message : err}`)
    isVisible = false
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (isVisible) recordVisible = true
else refuse(`${recordTypeName} ${recordId} not found`)

created = false
const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).disableAuthz().one()
if (email == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
const owners = []
if (email.emailAccountId) {
    const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess')
            .parameter('emailAccountId', email.emailAccountId).call()
    if (ec.message.hasError()) return
    if (!(access.level >= 1)) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
    if (access.account?.ownerUserId) owners.push(access.account.ownerUserId)
}
if (ec.user.userId) owners.push(ec.user.userId)
const out = ec.service.sync().name('mantle.party.CommunicationServices.create#EmailCommunicationEvent')
        .parameters({emailMessageId: emailMessageId, contactOwnerUserIdList: owners}).disableAuthz().call()
if (ec.message.hasError()) return
communicationEventId = out.communicationEventId ?? null
created = out.created === true

created = false
communicationEventId = null
matchedPartyIdList = []
if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('create#EmailCommunicationEvent is internal'); return }
const cf = ec.entity.conditionFactory
const eventOf = (id) => {
    if (!id) return null
    const found = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('emailMessageId', id)
            .orderBy('communicationEventId').limit(1).list()
    return found.length ? found[0] : null
}
const existing = eventOf(emailMessageId)
if (existing != null) { communicationEventId = existing.communicationEventId; return }
const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).one()
if (email == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }

// the addresses of a header: "Name, Title" <a@b>, c@d
const addressList = (text) => {
    const out = []
    if (!text) return out
    let current = '', quote = false, angle = 0
    const push = () => {
        const entry = current.trim()
        current = ''
        if (!entry) return
        const match = /<([^>]+)>\s*$/.exec(entry)
        const address = (match ? match[1] : entry).trim()
        if (address.includes('@') && !out.some((other) => other.toLowerCase() === address.toLowerCase())) out.push(address)
    }
    for (const ch of String(text)) {
        if (ch === '"') quote = !quote
        else if (ch === '<' && !quote) angle++
        else if (ch === '>' && !quote && angle > 0) angle--
        else if ((ch === ',' || ch === ';') && !quote && angle === 0) { push(); continue }
        current += ch
    }
    push()
    return out.slice(0, 100)
}
const owners = new Set((contactOwnerUserIdList ? Array.from(contactOwnerUserIdList) : []).filter((id) => id))
const ignored = new Set((ignoreAddressList ? Array.from(ignoreAddressList) : []).filter((address) => address)
        .map((address) => String(address).trim().toLowerCase()))
const byAddress = new Map()
const partyOfAddress = (address) => {
    const key = address.toLowerCase()
    if (byAddress.has(key)) return byAddress.get(key)
    let found = null
    const rows = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('contactMechTypeEnumId', 'CmtEmailAddress')
            .condition(cf.makeCondition('infoString', 'equals', address, false, true))
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('-fromDate').list())
    if (rows.length) {
        const parties = {}
        for (const party of ec.entity.find('mantle.party.Party').condition('partyId', 'in', Array.from(new Set(rows.map((row) => row.partyId))))
                .selectField('partyId').selectField('privateOwnerUserId').selectField('disabled').list()) parties[party.partyId] = party
        const allowed = rows.filter((row) => {
            const party = parties[row.partyId]
            return party != null && party.disabled !== 'Y' && (!party.privateOwnerUserId || owners.has(party.privateOwnerUserId))
        })
        const pick = allowed.find((row) => !parties[row.partyId].privateOwnerUserId) || allowed[0]
        if (pick) found = {partyId: pick.partyId, contactMechId: pick.contactMechId, address: address}
    }
    byAddress.set(key, found)
    return found
}
const partyOfUser = (userId) => {
    if (!userId) return null
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).useCache(true).one()
    return account?.partyId ? {partyId: account.partyId, contactMechId: null, address: null} : null
}

const fromAddress = addressList(email.fromAddress)[0] || null
const from = partyOfUser(email.fromUserId) || (fromAddress ? partyOfAddress(fromAddress) : null)
const toMatches = []
const toUser = partyOfUser(email.toUserId)
if (toUser) toMatches.push(toUser)
for (const address of addressList(email.toAddresses)) { const match = partyOfAddress(address); if (match) toMatches.push(match) }
const ccMatches = []
for (const address of addressList(email.ccAddresses)) { const match = partyOfAddress(address); if (match) ccMatches.push(match) }
const all = [from].concat(toMatches, ccMatches).filter((match) => match != null)
matchedPartyIdList = Array.from(new Set(all.map((match) => match.partyId)))
if (requireMatch && !all.some((match) => match.address == null || !ignored.has(match.address.toLowerCase()))) {
    matchedPartyIdList = []
    return
}
const to = toMatches[0] || null

const statusByEmail = {ES_DRAFT: 'CeInProgress', ES_SCHEDULED: 'CeInProgress', ES_READY: 'CeReady', ES_SENT: 'CeSent',
    ES_RECEIVED: 'CeReceived', ES_VIEWED: 'CeViewed', ES_BOUNCED: 'CeBounced', ES_CANCELLED: 'CeCancelled'}
const parent = eventOf(email.parentEmailMessageId)
const out = ec.service.sync().name('create#mantle.party.communication.CommunicationEvent').parameters({
    communicationEventTypeId: 'Email', contactMechTypeEnumId: 'CmtEmailAddress', emailMessageId: emailMessageId,
    statusId: statusByEmail[email.statusId] || (email.receivedDate ? 'CeReceived' : 'CeSent'),
    fromPartyId: from?.partyId ?? null, fromContactMechId: from?.contactMechId ?? null,
    toPartyId: to?.partyId ?? null, toContactMechId: to?.contactMechId ?? null,
    parentCommEventId: parent?.communicationEventId ?? null,
    rootCommEventId: parent ? (parent.rootCommEventId || parent.communicationEventId) : null,
    entryDate: email.sentDate ?? email.receivedDate ?? email.messageDate ?? ec.user.nowTimestamp, datetimeStarted: email.sentDate ?? null,
    subject: email.subject, body: email.body ?? email.bodyText, contentType: email.contentType}).call()
if (ec.message.hasError()) return
communicationEventId = out.communicationEventId
created = true
// the other recipients that match, one row per party, To before Cc
const roles = new Map()
for (const match of toMatches) if (!roles.has(match.partyId)) roles.set(match.partyId, 'MessageTo')
for (const match of ccMatches) if (!roles.has(match.partyId)) roles.set(match.partyId, 'MessageCc')
for (const [partyId, roleTypeId] of roles) {
    if (partyId === to?.partyId || partyId === from?.partyId) continue
    ec.service.sync().name('create#mantle.party.communication.CommunicationEventParty').parameters({
        communicationEventId: communicationEventId, partyId: partyId, roleTypeId: roleTypeId, statusId: 'CepReceived'}).call()
    if (ec.message.hasError()) return
}

created = false
if (!communicationEventId && emailMessageId) {
    const emailOut = ec.service.sync().name('mantle.party.CommunicationServices.findOrCreate#EmailCommunicationEvent')
            .parameter('emailMessageId', emailMessageId).call()
    if (ec.message.hasError()) return
    communicationEventId = emailOut.communicationEventId
}
if (!communicationEventId) { ec.message.addError('A communicationEventId or emailMessageId is required'); return }
const commEvent = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', communicationEventId).one()
if (commEvent == null) { ec.message.addError(`Communication event ${communicationEventId} not found`); return }

const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId,
            checkRecord: checkRecord !== false || !ec.artifactExecution.authzDisabled()}).call()
if (ec.message.hasError()) return
recordEntityName = info.recordEntityName

const createRow = (entityName, fields) => {
    ec.service.sync().name('create#' + entityName).parameters(fields).call()
    created = !ec.message.hasError()
}
if (info.isParty) {
    const isPost = !!commEvent.contactListId
    if (!isPost && (commEvent.fromPartyId === recordId || commEvent.toPartyId === recordId)) {
        linkEntityName = 'mantle.party.communication.CommunicationEvent'
    } else {
        linkEntityName = 'mantle.party.communication.CommunicationEventParty'
        let partyFind = ec.entity.find(linkEntityName).condition('communicationEventId', communicationEventId).condition('partyId', recordId)
        if (isPost) partyFind = partyFind.condition('roleTypeId', '_NA_')
        if (partyFind.list().length === 0) createRow(linkEntityName, {communicationEventId: communicationEventId, partyId: recordId, roleTypeId: '_NA_'})
    }
} else if (info.commEventJoin) {
    linkEntityName = info.commEventJoin.entityName
    const keys = {communicationEventId: communicationEventId, [info.commEventJoin.keyField]: recordId}
    if (ec.entity.find(linkEntityName).condition(keys).one() == null) createRow(linkEntityName, keys)
} else {
    linkEntityName = 'mantle.party.communication.CommunicationEventRecord'
    const keys = {communicationEventId: communicationEventId, recordEntityName: recordEntityName, recordId: recordId}
    if (ec.entity.find(linkEntityName).condition(keys).one() == null)
        createRow(linkEntityName, Object.assign({linkedByUserId: ec.user.userId, linkedDate: ec.user.nowTimestamp}, keys))
}
if (ec.message.hasError()) return

if (created && notifyFollowers) ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordFollowers').parameters({
    recordEntityName: recordEntityName, recordId: recordId, kind: commEvent.communicationEventTypeId === 'Comment' ? 'notes' : 'messages',
    communicationEventId: communicationEventId, subject: commEvent.subject, body: commEvent.body, recordUrl: recordUrl}).call()

unlinked = false
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
const removeRows = (entityName, keys) => {
    for (const row of ec.entity.find(entityName).condition(keys).list()) {
        ec.service.sync().name('delete#' + entityName).parameters(row.getPrimaryKeys()).call()
        if (ec.message.hasError()) return
        unlinked = true
    }
}
if (info.isParty) removeRows('mantle.party.communication.CommunicationEventParty',
        {communicationEventId: communicationEventId, partyId: recordId, roleTypeId: '_NA_'})
if (info.commEventJoin) removeRows(info.commEventJoin.entityName,
        {communicationEventId: communicationEventId, [info.commEventJoin.keyField]: recordId})
removeRows('mantle.party.communication.CommunicationEventRecord',
        {communicationEventId: communicationEventId, recordEntityName: info.recordEntityName, recordId: recordId})

const RECORD = 'mantle.party.communication.EmailMessageRecord'
sent = false
messageId = null
sendError = null
statusId = null
pendingRecordList = []
const scheduleAt = scheduledSendDate
scheduledSendDate = null
if (!!recordEntityName !== !!recordId) { ec.message.addError('A record is a recordEntityName with a recordId'); return }
const records = []
const addRecord = (entityName, id) => {
    if (!entityName || id == null || id === '') return
    if (!records.some((record) => record.recordEntityName === entityName && record.recordId === String(id)))
        records.push({recordEntityName: entityName, recordId: String(id)})
}
addRecord(recordEntityName, recordId)
for (const item of (recordList ? Array.from(recordList) : [])) {
    if (!item?.recordEntityName || item?.recordId == null) { ec.message.addError('Each record of recordList has a recordEntityName and a recordId'); return }
    addRecord(item.recordEntityName, item.recordId)
}
// each record under the user's filters, with its full entity name
const checked = []
for (const record of records) {
    const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
            .parameters({recordEntityName: record.recordEntityName, recordId: record.recordId}).call()
    if (ec.message.hasError()) return
    if (!checked.some((other) => other.recordEntityName === info.recordEntityName && other.recordId === record.recordId))
        checked.push({recordEntityName: info.recordEntityName, recordId: record.recordId})
}
// a draft the user may send from (send#Draft checks the rest)
const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
const draft = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).one()
if (draft == null || !access.accessMap[draft.emailAccountId]) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
if (access.accessMap[draft.emailAccountId] < 2) { ec.message.addError(`You may not send from email account ${draft.emailAccountId}`); return }

if (checked.length) {
    const now = ec.user.nowTimestamp
    for (const row of ec.entity.find(RECORD).condition('emailMessageId', emailMessageId).list()) {
        if (!checked.some((record) => record.recordEntityName === row.recordEntityName && record.recordId === row.recordId)) row.delete()
    }
    for (const record of checked) {
        const fields = {linkedByUserId: ec.user.userId, linkedDate: now, notifyFollowers: notifyFollowers ? 'Y' : 'N', recordUrl: recordUrl || null}
        const existing = ec.entity.find(RECORD).condition({emailMessageId: emailMessageId, recordEntityName: record.recordEntityName,
            recordId: record.recordId}).one()
        if (existing != null) {
            existing.setFields(fields, true, null, null)
            existing.update()
        } else {
            const row = ec.entity.makeValue(RECORD)
            row.setFields(Object.assign({emailMessageId: emailMessageId}, record, fields), true, null, null)
            row.create()
        }
    }
}

const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.send#Draft').parameters({emailMessageId: emailMessageId,
    scheduledSendDate: scheduleAt, holdSeconds: holdSeconds}).call()
if (ec.message.hasError()) return
statusId = out.statusId ?? null
sent = out.sent === true
messageId = out.messageId ?? null
sendError = out.sendError ?? null
scheduledSendDate = out.scheduledSendDate ?? null
pendingRecordList = Array.from(ec.entity.find(RECORD).condition('emailMessageId', emailMessageId).orderBy('recordEntityName,recordId').list())
        .map((row) => ({recordEntityName: row.recordEntityName, recordId: row.recordId}))

const RECORD = 'mantle.party.communication.EmailMessageRecord'
communicationEventId = null
filedRecordList = []
failedRecordList = []
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).forUpdate(true).one()
    if (email == null) { ec.entity.find(RECORD).condition('emailMessageId', emailMessageId).deleteAll(); return }
    if (email.statusId !== 'ES_SENT') return
    const pending = Array.from(ec.entity.find(RECORD).condition('emailMessageId', emailMessageId).orderBy('linkedDate').list())
    const account = email.emailAccountId ? ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', email.emailAccountId).one() : null
    const filing = account == null || account.accountKindEnumId === 'EakInternal' ? null
            : (account.recordFilingEnumId || (account.accountKindEnumId === 'EakExternal' ? 'ErfLinkedOnly' : 'ErfAllMatches'))
    if (pending.length === 0 && filing !== 'ErfAllMatches') return
    const ownAddresses = account == null ? [] : [account.emailAddress].concat(Array.from(ec.entity.find('moqui.basic.email.EmailIdentity')
            .condition('emailAccountId', account.emailAccountId).selectField('emailAddress').list()).map((identity) => identity.emailAddress))
            .filter((address) => address)
    const owners = [account?.ownerUserId].concat(pending.map((row) => row.linkedByUserId)).filter((id) => id)
    // the event, then each record's link, each in a transaction of its own: a record that fails leaves the rest filed
    const made = ec.service.sync().name('mantle.party.CommunicationServices.create#EmailCommunicationEvent').parameters({
        emailMessageId: emailMessageId, contactOwnerUserIdList: owners, requireMatch: pending.length === 0,
        ignoreAddressList: ownAddresses}).requireNewTransaction(true).disableAuthz().call()
    if (ec.message.hasError()) return
    communicationEventId = made.communicationEventId ?? null
    if (!communicationEventId) return
    for (const row of pending) {
        const record = {recordEntityName: row.recordEntityName, recordId: row.recordId}
        ec.message.pushErrors()
        try {
            const linked = ec.service.sync().name('mantle.party.CommunicationServices.link#CommunicationEventRecord').parameters({
                communicationEventId: communicationEventId, recordEntityName: row.recordEntityName, recordId: row.recordId,
                checkRecord: false, notifyFollowers: row.notifyFollowers === 'Y', recordUrl: row.recordUrl})
                .requireNewTransaction(true).disableAuthz().call()
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            // the generic link names the user who chose the record, not the one whose run filed it
            if (linked.created && linked.linkEntityName === 'mantle.party.communication.CommunicationEventRecord' && row.linkedByUserId) {
                ec.entity.find('mantle.party.communication.CommunicationEventRecord').condition({communicationEventId: communicationEventId,
                    recordEntityName: linked.recordEntityName, recordId: row.recordId})
                        .updateAll({linkedByUserId: row.linkedByUserId, linkedDate: row.linkedDate})
            }
            row.delete()
            record.linkEntityName = linked.linkEntityName ?? null
            filedRecordList.push(record)
        } catch (err) {
            record.message = err && err.message ? err.message : String(err)
            failedRecordList.push(record)
            ec.logger.error(`Sent email message ${emailMessageId} not filed on ${row.recordEntityName} ${row.recordId}: ${record.message}`)
        } finally {
            ec.message.clearErrors()
            ec.message.popErrors()
        }
    }
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

communicationEventId = null
created = false
matchedPartyIdList = []
notifiedUserIds = []
coalescedUserIds = []
failedSteps = []
const step = (name, run) => {
    ec.message.pushErrors()
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        failedSteps.push(name)
        ec.logger.error(`Received email message ${emailMessageId}: the ${name} step failed: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const email = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).one()
    if (email == null || !email.emailAccountId || !['ES_RECEIVED', 'ES_VIEWED'].includes(email.statusId)) return
    const account = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', email.emailAccountId).one()
    if (account == null || account.accountKindEnumId === 'EakInternal' || account.statusId === 'EasRemoved') return
    const folder = email.emailFolderId ? ec.entity.find('moqui.basic.email.EmailFolder').condition('emailFolderId', email.emailFolderId).one() : null
    if (folder != null && ['EfkDrafts', 'EfkSent', 'EfkJunk', 'EfkTrash'].includes(folder.folderKindEnumId)) return
    const filing = account.recordFilingEnumId || (account.accountKindEnumId === 'EakExternal' ? 'ErfLinkedOnly' : 'ErfAllMatches')
    if (filing === 'ErfAllMatches') step('filing', () => {
        const ownAddresses = [account.emailAddress].concat(Array.from(ec.entity.find('moqui.basic.email.EmailIdentity')
                .condition('emailAccountId', account.emailAccountId).selectField('emailAddress').list()).map((identity) => identity.emailAddress))
                .filter((address) => address)
        const out = ec.service.sync().name('mantle.party.CommunicationServices.create#EmailCommunicationEvent').parameters({
            emailMessageId: emailMessageId, contactOwnerUserIdList: account.ownerUserId ? [account.ownerUserId] : [],
            requireMatch: true, ignoreAddressList: ownAddresses}).requireNewTransaction(true).disableAuthz().call()
        if (ec.message.hasError()) return
        communicationEventId = out.communicationEventId ?? null
        created = out.created === true
        matchedPartyIdList = out.matchedPartyIdList ?? []
    })
    step('alert', () => {
        const out = ec.service.sync().name('mantle.party.CommunicationServices.notify#NewMail')
                .parameter('emailMessageId', emailMessageId).disableAuthz().call()
        notifiedUserIds = out?.notifiedUserIds ?? []
        coalescedUserIds = out?.coalescedUserIds ?? []
    })
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

serviceName = null
afterCommit = false
if (!emailMessageId) return
ec.message.pushErrors()
try {
    if (eecaOperation === 'delete') {
        ec.entity.find('mantle.party.communication.EmailMessageRecord').condition('emailMessageId', emailMessageId).disableAuthz().deleteAll()
        return
    }
    if (!emailAccountId) return
    if (statusId === 'ES_SENT' && (eecaOperation === 'create' || oldStatusId !== 'ES_SENT')) serviceName = 'mantle.party.CommunicationServices.file#SentEmail'
    else if (eecaOperation === 'create' && (statusId === 'ES_RECEIVED' || statusId === 'ES_VIEWED')) serviceName = 'mantle.party.CommunicationServices.file#ReceivedEmail'
    if (!serviceName) return
    try {
        ec.service.special().name(serviceName).parameters({emailMessageId: emailMessageId}).registerOnCommit()
        afterCommit = true
    } catch (err) {
        // no transaction in place: the write is committed already
        afterCommit = false
    }
    if (!afterCommit) {
        ec.service.sync().name(serviceName).parameter('emailMessageId', emailMessageId).requireNewTransaction(true).disableAuthz().call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    }
} catch (err) {
    ec.logger.error(`Email message ${emailMessageId}: ${serviceName || 'filing'} after the ${eecaOperation} not run: ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

entryList = []
plannedActivities = []
hasMore = false
nextBeforeDate = null
nextSeenKeys = []
failedSources = []
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
recordEntityName = info.recordEntityName

const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const kindNames = {message: 'message', messages: 'message', note: 'note', notes: 'note', activity: 'activity',
    activities: 'activity', change: 'change', changes: 'change', file: 'file', files: 'file'}
const kindValues = kinds == null ? [] : (typeof kinds === 'string' ? kinds.split(',') : Array.from(kinds))
const wanted = new Set(kindValues.map((kind) => kindNames[String(kind).trim()]).filter((kind) => kind))
const wants = (kind) => wanted.size === 0 || wanted.has(kind)
const start = pageIndex * pageSize
const need = start + pageSize + 1
const beforeMillis = toMillis(beforeDate)
// the cursor: with seenKeys the entries of beforeDate not shown yet come too
const seen = new Set(beforeMillis == null || seenKeys == null ? [] : (typeof seenKeys === 'string' ? seenKeys.split(',')
        : Array.from(seenKeys)).map((key) => String(key).trim()).filter((key) => key))
const inclusive = seen.size > 0
// each source's bound (before it): beforeDate, or with seenKeys the millisecond after it; and its limit, with
// room for the seen entries it may return
const before = beforeMillis == null ? null : new Date(inclusive ? beforeMillis + 1 : beforeMillis)
const fetch = need + seen.size
const entries = []

// one source: a failure (an exception or error messages) is logged and the source left out
const runSource = (name, run) => {
    try {
        run()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.message.clearErrors()
        ec.logger.error(`Record timeline of ${recordEntityName} ${recordId}: the ${name} source failed and is left out: ${err}`)
        failedSources.push(name)
    }
}
// a source service in a transaction of its own, so its failure rolls back only that
const callSource = (serviceName, parameters) =>
        ec.service.sync().name(serviceName).parameters(parameters).requireNewTransaction(true).call()

// messages and notes: communication events
if (wants('message') || wants('note')) runSource('communicationEvents', () => {
    const ids = new Set()
    if (info.isParty) {
        const typeIds = ec.entity.find('mantle.party.communication.CommunicationEventType').useCache(true).list()
                .map((type) => type.communicationEventTypeId).join(',')
        const parameters = {partyId: recordId, communicationEventTypeId: typeIds, includeListPosts: includeListPosts,
            orderByField: '-entryDate', pageIndex: 0, pageSize: fetch}
        if (before) parameters.entryDate_thru = new Date(before.getTime() - 1)
        const found = callSource('mantle.party.CommunicationServices.find#PartyCommunicationEvents', parameters)
        if (ec.message.hasError()) return
        for (const commEvent of found.commEventList) ids.add(commEvent.communicationEventId)
    } else {
        if (info.commEventJoin) for (const row of ec.entity.find(info.commEventJoin.entityName)
                .condition(info.commEventJoin.keyField, recordId).list()) ids.add(row.communicationEventId)
        for (const row of ec.entity.find('mantle.party.communication.CommunicationEventRecord')
                .condition('recordEntityName', recordEntityName).condition('recordId', recordId).list()) ids.add(row.communicationEventId)
    }
    if (ids.size === 0) return
    const idList = Array.from(ids)
    // for a record, the replies in the threads of its events too
    const idCondition = info.isParty ? cf.makeCondition('communicationEventId', 'in', idList) : cf.makeCondition([
        cf.makeCondition('communicationEventId', 'in', idList), cf.makeCondition('rootCommEventId', 'in', idList)], 'or')
    let find = ec.entity.find('mantle.party.communication.CommunicationEvent').condition(idCondition)
            .condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true)).orderBy('-entryDate').limit(fetch)
    if (before) find = find.condition(cf.makeCondition('entryDate', 'less', before))
    for (const value of find.list()) {
        const commEvent = value.getMap()
        const kind = commEvent.communicationEventTypeId === 'Comment' ? 'note' : 'message'
        if (!wants(kind)) continue
        entries.push({kind: kind, date: commEvent.entryDate ?? commEvent.datetimeStarted ?? commEvent.lastUpdatedStamp,
            entryKey: `ce:${commEvent.communicationEventId}`, authorPartyId: commEvent.fromPartyId ?? null, authorUserId: null,
            title: commEvent.subject ?? null,
            body: commEvent.body ?? null, contentType: commEvent.contentType ?? null, statusId: commEvent.statusId ?? null,
            source: 'mantle.party.communication.CommunicationEvent', communicationEventId: commEvent.communicationEventId,
            communicationEventTypeId: commEvent.communicationEventTypeId, fromPartyId: commEvent.fromPartyId ?? null,
            toPartyId: commEvent.toPartyId ?? null, parentCommEventId: commEvent.parentCommEventId ?? null,
            rootCommEventId: commEvent.rootCommEventId ?? null, emailMessageId: commEvent.emailMessageId ?? null,
            contactListId: commEvent.contactListId ?? null})
    }
})

// notes: the record's *Note rows
if (wants('note') && info.noteEntity) runSource('notes', () => {
    let find = ec.entity.find(info.noteEntity.entityName).condition(info.noteEntity.keyField, recordId)
            .orderBy('-noteDate').limit(fetch)
    if (before) find = find.condition(cf.makeCondition('noteDate', 'less', before))
    for (const value of find.list()) {
        const note = value.getMap()
        entries.push({kind: 'note', date: note.noteDate, entryKey: `note:${toMillis(note.noteDate)}`, authorPartyId: null,
            authorUserId: note.userId ?? null,
            title: null, body: note.noteText ?? null, contentType: 'text/plain', statusId: null,
            source: info.noteEntity.entityName, noteDate: note.noteDate, internalNote: note.internalNote ?? null})
    }
})

// activities: the record's calls, emails, to-dos and meetings; done ones in the timeline, open ones planned
if (wants('activity')) runSource('activities', () => {
    const ids = new Set()
    if (info.workEffortJoin) for (const row of ec.entity.find(info.workEffortJoin.entityName)
            .condition(info.workEffortJoin.keyField, recordId).list()) ids.add(row.workEffortId)
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortRecord').condition('recordEntityName', recordEntityName)
            .condition('recordId', recordId).list()) ids.add(row.workEffortId)
    if (ids.size === 0) return
    const nowMillis = toMillis(ec.user.nowTimestamp)
    const activities = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', Array.from(ids))
            .condition('purposeEnumId', 'in', ['WepPhoneCall', 'WepEmail', 'WepToDo', 'WepMeeting']).list()
    for (const value of activities) {
        const activity = value.getMap()
        if (activity.statusId === 'WeCancelled') continue
        const assignees = ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', activity.workEffortId)
                .condition('roleTypeId', 'Assignee').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
                .orderBy('-fromDate').limit(1).list()
        const assigneePartyId = assignees.length ? assignees[0].partyId : null
        if (activity.statusId === 'WeComplete' || activity.statusId === 'WeClosed') {
            const date = activity.actualCompletionDate ?? activity.estimatedCompletionDate ?? activity.actualStartDate ??
                    activity.estimatedStartDate ?? activity.lastUpdatedStamp
            if (before && toMillis(date) >= before.getTime()) continue
            entries.push({kind: 'activity', date: date, entryKey: `we:${activity.workEffortId}`, authorPartyId: assigneePartyId,
                authorUserId: null,
                title: activity.workEffortName ?? null, body: activity.description ?? null, contentType: null,
                statusId: activity.statusId, source: 'mantle.work.effort.WorkEffort', workEffortId: activity.workEffortId,
                purposeEnumId: activity.purposeEnumId})
        } else {
            const due = activity.purposeEnumId === 'WepMeeting' ? (activity.estimatedStartDate ?? activity.estimatedCompletionDate)
                    : (activity.estimatedCompletionDate ?? activity.estimatedStartDate)
            const dueMillis = toMillis(due)
            plannedActivities.push({workEffortId: activity.workEffortId, workEffortName: activity.workEffortName ?? null,
                description: activity.description ?? null, purposeEnumId: activity.purposeEnumId, statusId: activity.statusId,
                dueDate: dueMillis == null ? null : new Date(dueMillis), overdue: dueMillis != null && dueMillis < nowMillis,
                assigneePartyId: assigneePartyId})
        }
    }
    const dueOf = (activity) => activity.dueDate == null ? Number.MAX_SAFE_INTEGER : activity.dueDate.getTime()
    plannedActivities.sort((left, right) => dueOf(left) - dueOf(right))
})

// changes: the entity audit log of the record's enable-audit-log fields
if (wants('change')) runSource('auditLog', () => {
    let find = ec.entity.find('moqui.entity.EntityAuditLog').condition('changedEntityName', recordEntityName)
            .condition('pkPrimaryValue', recordId).condition(cf.makeCondition('pkSecondaryValue', 'is-null', null))
            .orderBy('-changedDate').limit(fetch).disableAuthz()
    if (before) find = find.condition(cf.makeCondition('changedDate', 'less', before))
    const statusDescription = (statusId) => {
        if (!statusId) return null
        const status = ec.entity.find('moqui.basic.StatusItem').condition('statusId', statusId).useCache(true).one()
        return status ? status.description : statusId
    }
    for (const value of find.list()) {
        const change = value.getMap()
        const isStatus = /statusId$/i.test(change.changedFieldName || '')
        const oldDescription = isStatus ? statusDescription(change.oldValueText) : null
        const newDescription = isStatus ? statusDescription(change.newValueText) : null
        entries.push({kind: 'change', date: change.changedDate, entryKey: `audit:${change.auditHistorySeqId}`, authorPartyId: null,
            authorUserId: change.changedByUserId ?? null,
            title: change.changedFieldName, body: `${oldDescription ?? change.oldValueText ?? ''} → ${newDescription ?? change.newValueText ?? ''}`,
            contentType: 'text/plain', statusId: null, source: 'moqui.entity.EntityAuditLog',
            auditHistorySeqId: change.auditHistorySeqId, fieldName: change.changedFieldName, oldValue: change.oldValueText ?? null,
            newValue: change.newValueText ?? null, oldValueDescription: oldDescription, newValueDescription: newDescription,
            changeReason: change.changeReason ?? null})
    }
})

// files: the record's *Content rows
if (wants('file') && info.contentEntity) runSource('content', () => {
    const contentInfo = info.contentEntity
    let find = ec.entity.find(contentInfo.entityName).condition(contentInfo.keyField, recordId)
            .orderBy('-' + contentInfo.dateField).limit(fetch)
    if (before) find = find.condition(cf.makeCondition(contentInfo.dateField, 'less', before))
    for (const value of find.list()) {
        const row = value.getMap()
        const location = row.contentLocation ? String(row.contentLocation) : ''
        entries.push({kind: 'file', date: row[contentInfo.dateField], entryKey: `file:${Object.values(value.getPrimaryKeys()).join('/')}`,
            authorPartyId: null, authorUserId: row.userId ?? null,
            title: location ? location.substring(location.lastIndexOf('/') + 1) : null, body: row.description ?? null,
            contentType: null, statusId: null, source: contentInfo.entityName, contentKey: value.getPrimaryKeys(),
            contentLocation: row.contentLocation ?? null, contentTypeEnumId: row[contentInfo.typeField] ?? null})
    }
})

// registered sources, such as a chat room bound to the record
const registered = ec.entity.find('moqui.service.ServiceRegister').condition('serviceTypeEnumId', 'RecordTimelineSource')
        .useCache(true).list()
for (const register of registered) runSource(register.serviceRegisterId, () => {
    const out = callSource(register.serviceName, {recordEntityName: recordEntityName, recordId: recordId,
        kinds: Array.from(wanted), beforeDate: before, limit: fetch})
    if (ec.message.hasError()) return
    for (const entry of (out?.entryList ?? [])) {
        const kind = kindNames[entry.kind] || entry.kind
        if (!wants(kind)) continue
        if (before && toMillis(entry.date) >= before.getTime()) continue
        const ownKey = entry.entryKey ?? entry.id ?? `${toMillis(entry.date)}:${entry.title ?? ''}`
        entries.push(Object.assign({source: register.serviceName}, entry,
                {kind: kind, entryKey: `${register.serviceRegisterId}:${ownKey}`}))
    }
})

// the union after the cursor, newest first (by entryKey within a date), and the page
const dateOf = (entry) => toMillis(entry.date) ?? 0
const after = beforeMillis == null ? entries : entries.filter((entry) => {
    const millis = dateOf(entry)
    return millis < beforeMillis || (inclusive && millis === beforeMillis && !seen.has(entry.entryKey))
})
after.sort((left, right) => dateOf(right) - dateOf(left)
        || (left.entryKey < right.entryKey ? 1 : left.entryKey > right.entryKey ? -1 : 0))
hasMore = after.length > start + pageSize
const page = after.slice(start, start + pageSize)
// the next page's cursor: the last entry's date and the keys shown so far of that date
if (page.length) {
    const lastMillis = dateOf(page[page.length - 1])
    nextBeforeDate = new Date(lastMillis)
    nextSeenKeys = after.slice(0, start + pageSize).filter((entry) => dateOf(entry) === lastMillis)
            .map((entry) => entry.entryKey)
    if (inclusive && lastMillis === beforeMillis) for (const key of seen) if (!nextSeenKeys.includes(key)) nextSeenKeys.push(key)
}
for (const entry of page) entry.date = entry.date == null ? null : new Date(dateOf(entry))

// the attachments of the messages and notes shown
const commEventIds = page.filter((entry) => entry.communicationEventId).map((entry) => entry.communicationEventId)
if (commEventIds.length) runSource('attachments', () => {
    const byEvent = {}
    for (const value of ec.entity.find('mantle.party.communication.CommunicationEventContent')
            .condition('communicationEventId', 'in', commEventIds).orderBy('sequenceNum,contentDate').list()) {
        const row = value.getMap()
        const location = row.contentLocation ? String(row.contentLocation) : ''
        ;(byEvent[row.communicationEventId] ??= []).push({communicationEventContentId: row.communicationEventContentId,
            contentLocation: row.contentLocation ?? null, fileName: location ? location.substring(location.lastIndexOf('/') + 1) : null,
            contentTypeEnumId: row.contentTypeEnumId ?? null, description: row.description ?? null})
    }
    for (const entry of page) if (entry.communicationEventId) entry.attachments = byEvent[entry.communicationEventId] ?? []
})
// the author's party of the entries that have only a user
const userIds = Array.from(new Set(page.filter((entry) => entry.authorUserId && !entry.authorPartyId).map((entry) => entry.authorUserId)))
if (userIds.length) runSource('authors', () => {
    const partyByUser = {}
    for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds).disableAuthz().list())
        partyByUser[account.userId] = account.partyId
    for (const entry of page) if (entry.authorUserId && !entry.authorPartyId) entry.authorPartyId = partyByUser[entry.authorUserId] ?? null
})
entryList = page

mentionedUserIds = []
notifiedFollowerUserIds = []
let rootCommEventId = null
if (parentCommEventId) {
    const parent = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('communicationEventId', parentCommEventId).one()
    if (parent == null) { ec.message.addError(`Communication event ${parentCommEventId} not found`); return }
    rootCommEventId = parent.rootCommEventId || parentCommEventId
}
const messageOut = ec.service.sync().name('mantle.party.CommunicationServices.create#Message').parameters({
    communicationEventTypeId: 'Comment', contactMechTypeEnumId: 'CmtWebForm', statusId: 'CeSent', subject: subject,
    body: body, contentType: contentType, parentCommEventId: parentCommEventId, rootCommEventId: rootCommEventId}).call()
if (ec.message.hasError()) return
communicationEventId = messageOut.communicationEventId
const linkOut = ec.service.sync().name('mantle.party.CommunicationServices.link#CommunicationEventRecord')
        .parameters({communicationEventId: communicationEventId, recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
linkEntityName = linkOut.linkEntityName

const notifyParameters = {recordEntityName: linkOut.recordEntityName, recordId: recordId, communicationEventId: communicationEventId,
    subject: subject, body: body, recordUrl: recordUrl}
if (mentionUserIds?.length || mentionPartyIds?.length) {
    const mentionOut = ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordMention')
            .parameters(Object.assign({mentionUserIds: mentionUserIds, mentionPartyIds: mentionPartyIds}, notifyParameters)).call()
    if (ec.message.hasError()) return
    mentionedUserIds = mentionOut.notifiedUserIds
}
const followerOut = ec.service.sync().name('mantle.party.CommunicationServices.notify#RecordFollowers')
        .parameters(Object.assign({kind: 'notes', excludeUserIds: mentionedUserIds}, notifyParameters)).call()
if (ec.message.hasError()) return
notifiedFollowerUserIds = followerOut.notifiedUserIds

notifiedUserIds = []
const userIds = new Set(mentionUserIds ? Array.from(mentionUserIds) : [])
if (mentionPartyIds?.length) for (const account of ec.entity.find('moqui.security.UserAccount')
        .condition('partyId', 'in', Array.from(mentionPartyIds)).disableAuthz().list()) userIds.add(account.userId)
userIds.delete(authorUserId)
if (userIds.size === 0) return
const message = ec.service.sync().name('mantle.party.CommunicationServices.make#RecordNotificationMessage').parameters({
    recordEntityName: recordEntityName, recordId: recordId, communicationEventId: communicationEventId, subject: subject,
    body: body, authorUserId: authorUserId}).call().message
try {
    const nm = ec.makeNotificationMessage().topic('ChatterMention').message(message).userIds(Array.from(userIds))
    if (recordUrl) nm.link(recordUrl)
    nm.send()
    notificationMessageId = nm.getNotificationMessageId()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? [])
} catch (err) {
    ec.logger.error(`Mention notification for ${recordEntityName} ${recordId} not sent: ${err}`)
}

notifiedUserIds = []
const flagFields = {messages: 'notifyMessages', notes: 'notifyNotes', activities: 'notifyActivities', changes: 'notifyChanges'}
const flagField = flagFields[kind]
if (!flagField) { ec.message.addError(`Follower kind ${kind} is not one of messages, notes, activities, changes`); return }
const excluded = new Set(excludeUserIds ? Array.from(excludeUserIds) : [])
excluded.add(authorUserId)
const userIds = ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', recordEntityName)
        .condition('recordId', recordId).condition(flagField, 'Y').list()
        .map((follower) => follower.userId).filter((userId) => !excluded.has(userId))
if (userIds.length === 0) return
const message = ec.service.sync().name('mantle.party.CommunicationServices.make#RecordNotificationMessage').parameters({
    recordEntityName: recordEntityName, recordId: recordId, communicationEventId: communicationEventId, subject: subject,
    body: body, authorUserId: authorUserId}).call().message
message.kind = kind
message.workEffortId = workEffortId ?? null
try {
    const nm = ec.makeNotificationMessage().topic('RecordFollow').message(message).userIds(userIds)
    if (recordUrl) nm.link(recordUrl)
    nm.send()
    notificationMessageId = nm.getNotificationMessageId()
    notifiedUserIds = Array.from(nm.getNotifyUserIds() ?? [])
} catch (err) {
    ec.logger.error(`Follower notification for ${recordEntityName} ${recordId} not sent: ${err}`)
}

let recordTypeName = recordEntityName.substring(recordEntityName.lastIndexOf('.') + 1)
try { recordTypeName = ec.entity.makeValue(recordEntityName).getEntityNamePretty() } catch (err) { /* the short name */ }
const author = authorUserId ? ec.entity.find('moqui.security.UserAccount').condition('userId', authorUserId).disableAuthz().one() : null
const text = body ? String(body).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim() : ''
message = {recordEntityName: recordEntityName, recordId: recordId, recordName: `${recordTypeName} ${recordId}`,
    communicationEventId: communicationEventId ?? null, authorUserId: authorUserId ?? null,
    authorName: author ? (author.userFullName || author.username) : 'Someone', subject: subject ?? null,
    summary: subject || (text.length > 120 ? text.substring(0, 117) + '...' : text)}

if (!userId) { ec.message.addError('A user is required to follow a record'); return }
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
const flagFields = {messages: 'notifyMessages', notes: 'notifyNotes', activities: 'notifyActivities', changes: 'notifyChanges'}
const keys = {recordEntityName: info.recordEntityName, recordId: recordId, userId: userId}
const existing = ec.entity.find('mantle.party.communication.RecordFollower').condition(keys).one()
let flags = null
const kindList = (kinds == null ? [] : (typeof kinds === 'string' ? kinds.split(',') : Array.from(kinds)))
        .map((kind) => String(kind).trim()).filter((kind) => kind)
if (kindList.length) {
    const unknown = kindList.filter((kind) => !flagFields[kind])
    if (unknown.length) { ec.message.addError(`Follower kinds ${unknown.join(', ')} are not messages, notes, activities or changes`); return }
    flags = {}
    for (const [kind, field] of Object.entries(flagFields)) flags[field] = kindList.includes(kind) ? 'Y' : 'N'
}
if (existing != null) {
    fromDate = existing.fromDate
    if (flags) ec.service.sync().name('update#mantle.party.communication.RecordFollower').parameters(Object.assign({}, keys, flags)).call()
} else {
    fromDate = ec.user.nowTimestamp
    ec.service.sync().name('create#mantle.party.communication.RecordFollower').parameters(Object.assign({fromDate: fromDate},
            flags || {notifyMessages: 'Y', notifyNotes: 'Y', notifyActivities: 'Y', notifyChanges: 'N'}, keys)).call()
}

let entityName = recordEntityName
try { entityName = ec.entity.makeValue(recordEntityName).getEntityName() } catch (err) { /* as given */ }
const keys = {recordEntityName: entityName, recordId: recordId, userId: userId}
if (ec.entity.find('mantle.party.communication.RecordFollower').condition(keys).one() != null)
    ec.service.sync().name('delete#mantle.party.communication.RecordFollower').parameters(keys).call()

followerList = []
isFollowing = false
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
for (const follower of ec.entity.find('mantle.party.communication.RecordFollower').condition('recordEntityName', info.recordEntityName)
        .condition('recordId', recordId).orderBy('fromDate').list()) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', follower.userId).disableAuthz().one()
    followerList.push({userId: follower.userId, username: account?.username ?? null, userFullName: account?.userFullName ?? null,
        partyId: account?.partyId ?? null, notifyMessages: follower.notifyMessages, notifyNotes: follower.notifyNotes,
        notifyActivities: follower.notifyActivities, notifyChanges: follower.notifyChanges, fromDate: follower.fromDate})
    if (follower.userId === ec.user.userId) isFollowing = true
}
